export function validateServiceDefinition(def: unknown): ServiceDefinition {
  if (typeof def !== 'object' || def === null) {
    throw new TypeError('ServiceDefinition must be an object');
  }
  const d = def as Record<string, unknown>;
  if (typeof d['name'] !== 'string' || d['name'].trim() === '') {
    throw new TypeError('ServiceDefinition.name must be a non-empty string');
  }
  if (typeof d['command'] !== 'string' || d['command'].trim() === '') {
    throw new TypeError('ServiceDefinition.command must be a non-empty string');
  }
  if (!Array.isArray(d['args']) || !d['args'].every((a) => typeof a === 'string')) {
    throw new TypeError('ServiceDefinition.args must be an array of strings');
  }
  return {
    name: d['name'],
    command: d['command'],
    args: d['args'] as string[],
    cwd: typeof d['cwd'] === 'string' ? d['cwd'] : undefined,
    env: typeof d['env'] === 'object' && d['env'] !== null ? (d['env'] as Record<string, string>) : undefined,
    readinessPolicy: typeof d['readinessPolicy'] === 'object' && d['readinessPolicy'] !== null
      ? (d['readinessPolicy'] as ServiceDefinition['readinessPolicy'])
      : undefined,
  };
}

export function validateServiceTable(table: unknown): ServiceTable {
  if (typeof table !== 'object' || table === null) {
    throw new TypeError('ServiceTable must be an object');
  }
  const t = table as Record<string, unknown>;
  if (typeof t['version'] !== 'string') {
    throw new TypeError('ServiceTable.version must be a string');
  }
  if (typeof t['defaultPorts'] !== 'object' || t['defaultPorts'] === null) {
    throw new TypeError('ServiceTable.defaultPorts must be an object');
  }
  if (!Array.isArray(t['services'])) {
    throw new TypeError('ServiceTable.services must be an array');
  }

  const validatedServices = t['services'].map((s) => validateServiceDefinition(s));

  return {
    version: t['version'],
    defaultPorts: t['defaultPorts'] as ServicePorts,
    services: validatedServices,
  };
}

export function createBackendEnvironment(params: {
  backendPath: string;
  dataFolder: string;
  encryptionKey: string;
  tiktokenCache: string;
  apiPort?: number | undefined;
  existingEnv?: Record<string, string | undefined> | undefined;
}): BackendEnvironment {
  const {
    backendPath,
    dataFolder,
    encryptionKey,
    tiktokenCache,
    apiPort = DEFAULT_PORTS.api,
    existingEnv = process.env,
  } = params;

  return {
    ...existingEnv,
    PYTHONPATH: backendPath,
    PYTHONUNBUFFERED: '1',
    PYTHONUTF8: '1',
    DATA_FOLDER: dataFolder,
    SURREAL_URL: 'ws://127.0.0.1:8000/rpc',
    SURREAL_USER: 'root',
    SURREAL_PASSWORD: 'root',
    SURREAL_NAMESPACE: 'open_notebook',
    SURREAL_DATABASE: 'open_notebook',
    OPEN_NOTEBOOK_ENCRYPTION_KEY: encryptionKey,
    OPEN_NOTEBOOK_ENABLE_DOCLING: 'true',
    TIKTOKEN_CACHE_DIR: tiktokenCache,
    API_HOST: '127.0.0.1',
    API_PORT: String(apiPort),
  };
}

/**
 * Pure wrapper module for parsing and verifying runtime manifests and paths.
 */

import {
  RuntimeManifest,
  RuntimeVerificationResult,
} from '../types';

export const REQUIRED_RUNTIME_PATHS = [
  'surreal/surreal.exe',
  'backend/open_notebook',
  'frontend/server.js',
] as const;

export const OPTIONAL_BUNDLE_PATHS = [
  'python/python.exe',
  'node/node.exe',
  'tiktoken-cache',
] as const;

export interface ManifestValidationResult {
  valid: boolean;
  errors: readonly string[];
  manifest?: RuntimeManifest | undefined;
}

/**
 * Validates whether an object matches the RuntimeManifest contract structure.
 */
export function validateRuntimeManifest(data: unknown): ManifestValidationResult {
  const errors: string[] = [];

  if (data === null || typeof data !== 'object') {
    return { valid: false, errors: ['Manifest data must be a non-null object'] };
  }

  const obj = data as Record<string, unknown>;

  if (typeof obj['upstreamCommit'] !== 'string' || obj['upstreamCommit'].trim() === '') {
    errors.push('Manifest missing valid upstreamCommit string');
  }

  if (obj['buildTimestamp'] !== undefined && typeof obj['buildTimestamp'] !== 'string') {
    errors.push('Manifest buildTimestamp must be a string if provided');
  }

  if (obj['version'] !== undefined && typeof obj['version'] !== 'string') {
    errors.push('Manifest version must be a string if provided');
  }

  if (obj['wrapperCommit'] !== undefined && typeof obj['wrapperCommit'] !== 'string') {
    errors.push('Manifest wrapperCommit must be a string if provided');
  }

  if (obj['targetArchitecture'] !== undefined && typeof obj['targetArchitecture'] !== 'string') {
    errors.push('Manifest targetArchitecture must be a string if provided');
  }

  if (errors.length > 0) {
    return { valid: false, errors };
  }

  const manifest: RuntimeManifest = {
    upstreamCommit: String(obj['upstreamCommit']),
    ...(typeof obj['buildTimestamp'] === 'string' ? { buildTimestamp: obj['buildTimestamp'] } : {}),
    ...(typeof obj['version'] === 'string' ? { version: obj['version'] } : {}),
  };

  return { valid: true, errors: [], manifest };
}

/**
 * Parses JSON or an existing object into a typed RuntimeManifest.
 */
export function parseRuntimeManifest(input: string | unknown): RuntimeManifest {
  let parsed: unknown;
  if (typeof input === 'string') {
    try {
      parsed = JSON.parse(input);
    } catch (err) {
      throw new Error(`Failed to parse runtime manifest JSON: ${err instanceof Error ? err.message : String(err)}`);
    }
  } else {
    parsed = input;
  }

  const validation = validateRuntimeManifest(parsed);
  if (!validation.valid || !validation.manifest) {
    throw new Error(`Invalid runtime manifest format: ${validation.errors.join('; ')}`);
  }

  return validation.manifest;
}

/**
 * Verifies that required runtime files and directories exist under runtimePath.
 */
export function verifyRuntimePaths(
  runtimePath: string,
  fileExistsFn: (filePath: string) => boolean
): RuntimeVerificationResult {
  const missingPaths: string[] = [];

  for (const relPath of REQUIRED_RUNTIME_PATHS) {
    const fullPath = `${runtimePath}/${relPath}`.replace(/\/+/g, '/');
    if (!fileExistsFn(fullPath)) {
      missingPaths.push(relPath);
    }
  }

  return {
    valid: missingPaths.length === 0,
    missingPaths,
  };
}

/**
 * Pure wrapper module for resolving Python and Node.js executables.
 */

import { PythonResolution, NodeResolution } from '../types';

export interface ResolutionOptions {
  fileExists: (filePath: string) => boolean;
  findOnPath: (command: string) => string | null;
  getVersion: (cmdPath: string, args: readonly string[]) => string | null;
  pathJoin?: (...parts: string[]) => string;
}

const defaultJoin = (...parts: string[]): string =>
  parts.join('/').replace(/\/+/g, '/');

/**
 * Parses Python version string (e.g. "Python 3.12.2" or "3.11.4").
 */
export function parsePythonVersion(versionString: string): { major: number; minor: number } | null {
  const match = versionString.match(/(?:Python\s+)?(\d+)\.(\d+)/i);
  if (!match || !match[1] || !match[2]) return null;
  const major = parseInt(match[1], 10);
  const minor = parseInt(match[2], 10);
  if (isNaN(major) || isNaN(minor)) return null;
  return { major, minor };
}

/**
 * Parses Node version string (e.g. "v22.14.0" or "v18.20.1" or "20.0.0").
 */
export function parseNodeVersion(versionString: string): { major: number } | null {
  const match = versionString.match(/v?(\d+)/i);
  if (!match || !match[1]) return null;
  const major = parseInt(match[1], 10);
  if (isNaN(major)) return null;
  return { major };
}

/**
 * Pure resolution logic for Python. Checks bundled path first, then system PATH.
 */
export function resolvePython(
  runtimePath: string,
  opts: ResolutionOptions
): PythonResolution | null {
  const join = opts.pathJoin || defaultJoin;
  const bundled = join(runtimePath, 'python', 'python.exe');

  if (opts.fileExists(bundled)) {
    return { path: bundled, source: 'bundled' };
  }

  const system = opts.findOnPath('python.exe') || opts.findOnPath('python');
  if (!system) {
    return null;
  }

  const versionOut = opts.getVersion(system, ['--version']);
  if (!versionOut) {
    return null;
  }

  const parsed = parsePythonVersion(versionOut);
  if (!parsed) {
    return null;
  }

  const { major, minor } = parsed;
  if (major !== 3 || minor < 11 || minor >= 13) {
    return { path: system, source: 'system', invalidVersion: `${major}.${minor}` };
  }

  return { path: system, source: 'system' };
}

/**
 * Pure resolution logic for Node.js. Checks bundled path first, then system PATH.
 */
export function resolveNode(
  runtimePath: string,
  opts: ResolutionOptions
): NodeResolution | null {
  const join = opts.pathJoin || defaultJoin;
  const bundled = join(runtimePath, 'node', 'node.exe');

  if (opts.fileExists(bundled)) {
    return { path: bundled, source: 'bundled' };
  }

  const system = opts.findOnPath('node.exe') || opts.findOnPath('node');
  if (!system) {
    return null;
  }

  const versionOut = opts.getVersion(system, ['--version']);
  if (!versionOut) {
    return null;
  }

  const parsed = parseNodeVersion(versionOut);
  if (!parsed) {
    return null;
  }

  const { major } = parsed;
  if (major < 18) {
    return { path: system, source: 'system', invalidVersion: major };
  }

  return { path: system, source: 'system' };
}

/**
 * Pure wrapper module for window navigation policy and URL origin verification.
 */

import { NavigationDecision } from '../types';

/**
 * Evaluates whether a navigation target URL should be allowed internally,
 * opened in an external browser, or denied.
 */
export function evaluateNavigationPolicy(
  targetUrl: string,
  frontendUrl: string = 'http://127.0.0.1:8502'
): NavigationDecision {
  if (!targetUrl || typeof targetUrl !== 'string') {
    return {
      action: 'deny',
      targetUrl: String(targetUrl || ''),
      reason: 'Target URL is missing or non-string',
    };
  }

  const normalizedTarget = targetUrl.trim();
  const normalizedFrontend = frontendUrl.trim().replace(/\/+$/, '');

  // Check if target is internal frontend navigation
  if (
    normalizedTarget.startsWith(normalizedFrontend + '/') ||
    normalizedTarget === normalizedFrontend
  ) {
    return {
      action: 'allow',
      targetUrl: normalizedTarget,
      reason: 'Internal navigation within frontend application',
    };
  }

  // Check if target is external HTTP or HTTPS link
  if (
    normalizedTarget.startsWith('http://') ||
    normalizedTarget.startsWith('https://')
  ) {
    return {
      action: 'external',
      targetUrl: normalizedTarget,
      reason: 'External HTTP(S) link delegated to OS browser',
    };
  }

  // All other protocols (file://, javascript:, custom schemes, etc.) are denied
  return {
    action: 'deny',
    targetUrl: normalizedTarget,
    reason: 'Unsupported or untrusted protocol',
  };
}

/**
 * Office of Equity Open Notebook — Process Manager & Supervision Contracts
 *
 * Strict TypeScript implementation of process management, port polling,
 * service lifecycle handling, log formatting, and graceful shutdown semantics.
 */

import net from 'net';
import {
  ServicePorts,
  ServiceName,
  ServiceExitEvent,
  StartServicesConfig,
} from '../types';

export const DEFAULT_SERVICE_PORTS: ServicePorts = Object.freeze({
  surreal: 8000,
  api: 5055,
  frontend: 8502,
});

export function isPortOpen(port: number, host = '127.0.0.1'): Promise<boolean> {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    const onDone = (ok: boolean) => {
      socket.destroy();
      resolve(ok);
    };
    socket.setTimeout(1000);
    socket.once('connect', () => onDone(true));
    socket.once('timeout', () => onDone(false));
    socket.once('error', () => onDone(false));
    socket.connect(port, host);
  });
}

export function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

export async function waitForPort(
  port: number,
  timeoutMs = 60000,
  label: string = String(port),
  host = '127.0.0.1',
  portCheckFn: (p: number, h?: string) => Promise<boolean> = isPortOpen
): Promise<boolean> {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (await portCheckFn(port, host)) return true;
    await sleep(500);
  }
  throw new Error(`Timed out waiting for ${label} on port ${port}`);
}

export function formatLogLine(
  name: string,
  stream: 'out' | 'err',
  data: string | Buffer,
  timestamp: Date = new Date()
): string | null {
  const line = String(data).trimEnd();
  if (!line) return null;
  const tag = `[${name}:${stream}]`;
  const formattedTimestamp = timestamp.toISOString();
  return `${formattedTimestamp} ${tag} ${line}\n`;
}

export function calculateShutdownSequence<T>(items: readonly T[]): T[] {
  return [...items].reverse();
}

export function createServiceExitEvent(
  serviceName: ServiceName,
  exitCode: number | null,
  signal: string | null,
  killedIntentional: boolean
): ServiceExitEvent {
  const unexpected = !killedIntentional && exitCode !== 0 && exitCode !== null;
  return {
    serviceName,
    exitCode,
    signal,
    unexpected,
    timestamp: new Date().toISOString(),
  };
}

export function validateStartServicesConfig(cfg: unknown): StartServicesConfig {
  if (typeof cfg !== 'object' || cfg === null) {
    throw new TypeError('StartServicesConfig must be an object');
  }
  const c = cfg as Record<string, unknown>;
  if (typeof c['runtimePath'] !== 'string' || c['runtimePath'].trim() === '') {
    throw new TypeError('StartServicesConfig.runtimePath must be a non-empty string');
  }
  if (typeof c['dataDir'] !== 'string' || c['dataDir'].trim() === '') {
    throw new TypeError('StartServicesConfig.dataDir must be a non-empty string');
  }
  if (typeof c['encryptionKey'] !== 'string' || c['encryptionKey'].trim() === '') {
    throw new TypeError('StartServicesConfig.encryptionKey must be a non-empty string');
  }
  return {
    runtimePath: c['runtimePath'],
    dataDir: c['dataDir'],
    encryptionKey: c['encryptionKey'],
    waitReady: typeof c['waitReady'] === 'boolean' ? c['waitReady'] : undefined,
    customPorts: typeof c['customPorts'] === 'object' && c['customPorts'] !== null
      ? (c['customPorts'] as Partial<ServicePorts>)
