          const inp = sc.input as { services: string[] };
          actual = calculateShutdownSequence(inp.services);
          const exp = sc.expectedOutput as { sequence: string[] };
          passed = JSON.stringify(actual) === JSON.stringify(exp.sequence);
          break;
