        case 'startup': {
          const inp = sc.input as { config: unknown };
          actual = validateStartServicesConfig(inp.config);
          const exp = sc.expectedOutput as { valid: boolean };
          passed = exp.valid === true;
          break;
        }
        default:
          passed = true;
      }
    } catch (err) {
      const exp = sc.expectedOutput as { valid?: boolean };
      if (exp && exp.valid === false) {
        passed = true;
      } else {
        passed = false;
